import fs from 'node:fs';
import path from 'node:path';

// Node ships two realpath implementations:
//   - fs.realpath / fs.realpathSync: a JS reimplementation that walks the path
//     with lstat/readlink. Its output has varied across Node versions and
//     platforms (e.g. drive-letter and path casing on Windows/macOS).
//   - fs.realpath.native / fs.realpathSync.native / fs.promises.realpath:
//     thin wrappers over libuv's uv_fs_realpath (realpath(3) on POSIX,
//     GetFinalPathNameByHandleW on Windows). Behaviour is defined by the OS,
//     so it is stable across Node versions.
// We use the native implementation, falling back to the JS one only for
// filesystems where the native call is known to fail (some Windows virtual
// drives, RAM disks and network shares report EISDIR/ENOTSUP/EPERM etc.).

// Errors that mean "the path genuinely can't be resolved" - never fall back.
const FATAL_CODES = new Set(['ENOENT', 'ENOTDIR', 'ELOOP', 'EACCES', 'ENAMETOOLONG']);

function shouldFallBack(err) {
  return err && typeof err.code === 'string' && !FATAL_CODES.has(err.code);
}

/**
 * Resolve `p` (relative paths are resolved against process.cwd()) to its
 * canonical absolute path with all symlinks, `.` and `..` resolved.
 * Rejects with ENOENT if any component does not exist.
 *
 * @param {string | URL | Buffer} p
 * @returns {Promise<string>}
 */
export async function canonicalPath(p) {
  const abs = toAbsolute(p);
  try {
    return await fs.promises.realpath(abs);
  } catch (err) {
    if (!shouldFallBack(err)) throw err;
    return fs.promises.realpath === undefined
      ? Promise.reject(err)
      : new Promise((resolve, reject) =>
          fs.realpath(abs, (e, r) => (e ? reject(e) : resolve(r))),
        );
  }
}

/**
 * Synchronous variant of {@link canonicalPath}.
 *
 * @param {string | URL | Buffer} p
 * @returns {string}
 */
export function canonicalPathSync(p) {
  const abs = toAbsolute(p);
  try {
    return fs.realpathSync.native(abs);
  } catch (err) {
    if (!shouldFallBack(err)) throw err;
    return fs.realpathSync(abs);
  }
}

function toAbsolute(p) {
  if (p instanceof URL) return path.resolve(fileURLToPathStrict(p));
  if (Buffer.isBuffer(p)) p = p.toString();
  if (typeof p !== 'string' || p.length === 0) {
    throw new TypeError('path must be a non-empty string, Buffer, or file: URL');
  }
  return path.resolve(p);
}

function fileURLToPathStrict(u) {
  if (u.protocol !== 'file:') throw new TypeError(`Unsupported URL protocol: ${u.protocol}`);
  // Imported lazily to keep the top-level import list minimal.
  return decodeURIComponent(new URL(u).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
}
